import { test } from "node:test";
import assert from "node:assert/strict";
import { resolveEnvironment } from "../src/env/environment.ts";
import { executePayroll, type PayrollRun } from "../src/payroll/payrollRun.ts";
import type { HttpTransport } from "../src/payroll/bank.ts";
import type { Mailer } from "../src/payroll/notify.ts";

function fakes() {
    const posts: string[] = [];
    const mail: { to: string; subject: string }[] = [];
    const http: HttpTransport = {
        async post(url) {
            posts.push(url);
            return { status: 201, body: { transferId: `tr-${posts.length}` } };
        },
    };
    const mailer: Mailer = { send: async (to, subject) => void mail.push({ to, subject }) };
    return { posts, mail, http, mailer };
}

const run: PayrollRun = {
    period: "2026-11",
    approvedBy: "cfo@corp.example",
    employees: [
        { id: "e1", email: "mia@corp.example", iban: "DE89370400440532013000", netCents: 412_000 },
        { id: "e2", email: "omar@corp.example", iban: "DE02120300000000202051", netCents: 389_550 },
    ],
};

test("production pays through the live bank and emails employees directly", async () => {
    const env = resolveEnvironment({ APP_ENV: "production" });
    assert.deepEqual([env.bank.mode, env.emailRedirect, env.requireApproval], ["live", null, true]);
    const { posts, mail, http, mailer } = fakes();
    const result = await executePayroll(env, http, mailer, run);
    assert.equal(result.paid.length, 2);
    assert.ok(posts.every((u) => u === "https://api.bank.example/v2/transfers"));
    assert.deepEqual(mail.map((m) => m.to), ["mia@corp.example", "omar@corp.example"]);
});

test("aliases are accepted, unknown names are rejected, and a missing APP_ENV means development", () => {
    assert.equal(resolveEnvironment({ APP_ENV: " Prod " }).name, "production");
    assert.equal(resolveEnvironment({ APP_ENV: "stage" }).name, "staging");
    assert.throws(() => resolveEnvironment({ APP_ENV: "qa" }), /unknown APP_ENV "qa"/);
    const dev = resolveEnvironment({});
    assert.deepEqual([dev.name, dev.bank.mode, dev.logLevel], ["development", "sandbox", "debug"]);
});

test("a live payroll run without a second approver pays nobody", async () => {
    const { posts, http, mailer } = fakes();
    await assert.rejects(executePayroll(resolveEnvironment({ APP_ENV: "prod" }), http, mailer, { ...run, approvedBy: undefined }), /second approver/);
    assert.deepEqual(posts, []);
});

test("staging uses the bank sandbox and the QA inbox without needing approval", async () => {
    const env = resolveEnvironment({ APP_ENV: "staging", EMAIL_REDIRECT: "qa-team@corp.example" });
    const { posts, mail, http, mailer } = fakes();
    await executePayroll(env, http, mailer, { ...run, approvedBy: undefined });
    assert.ok(posts.every((u) => u.startsWith("https://sandbox.bank.example/")));
    assert.deepEqual(mail.map((m) => m.to), ["qa-team@corp.example", "qa-team@corp.example"]);
    assert.equal(mail[0].subject, "[staging → mia@corp.example] Your payslip for 2026-11 is ready");
});

test("preview environments are not treated as production", () => {
    const env = resolveEnvironment({ APP_ENV: "preview" });
    assert.deepEqual(
        { isProduction: env.isProduction, bank: env.bank.mode, redirect: env.emailRedirect, approval: env.requireApproval },
        { isProduction: false, bank: "sandbox", redirect: "payroll-qa@corp.example", approval: false },
    );
});

test("a payroll run in a preview environment moves no real money and emails no employee", async () => {
    const { posts, mail, http, mailer } = fakes();
    await executePayroll(resolveEnvironment({ APP_ENV: "preview" }), http, mailer, run);
    console.log("bank calls from preview:", posts, "emails to:", mail.map((m) => m.to));
    assert.ok(posts.length === 2 && posts.every((u) => u.startsWith("https://sandbox.bank.example/")));
    assert.ok(mail.every((m) => m.to === "payroll-qa@corp.example"));
});

test("only production logs at info level", () => {
    const levels = ["development", "test", "preview", "staging", "production"].map((n) => resolveEnvironment({ APP_ENV: n }).logLevel);
    assert.deepEqual(levels, ["debug", "debug", "debug", "debug", "info"]);
});
